use std::sync::Arc;
use std::time::Instant;

use winit::application::ApplicationHandler;
use winit::event::{ElementState, MouseButton, WindowEvent};
use winit::event_loop::ActiveEventLoop;
use winit::window::{Icon, Window, WindowId};

/// Raw RGBA8 pixels (256×256, sRGB) for the window icon. Generated by
/// `scripts/gen-icons.sh` from `assets/icon.svg`. Embedded as raw bytes so
/// the runtime doesn't need a PNG decoder.
const ICON_RGBA: &[u8] = include_bytes!("../../../assets/generated/icon-256.rgba");
const ICON_SIZE: u32 = 256;

use locus_ops::Command;
use locus_render::Renderer;
use locus_scene::NodeData;
use locus_tools::{SelectState, TextAction, ToolType};

use crate::context_menu::show_canvas_context_menu;
use crate::editor_state::{CanvasContextMenu, CanvasContextTarget, EditorState};
use crate::llm_dialog;
use crate::preview_group::DialogAction;
use crate::script_dialog;
use crate::structure_panel::{StructureAction, apply_structure_action};
use crate::trace_dialog;
use crate::ui::run_ui;

/// Classification of a file dropped onto the window.
#[derive(Copy, Clone, Debug)]
enum DroppedKind {
    Svg,
    Raster,
}

impl DroppedKind {
    fn label(self) -> &'static str {
        match self {
            DroppedKind::Svg => "SVG",
            DroppedKind::Raster => "raster image",
        }
    }
}

/// Initialized GPU + window state. Created on first resume.
struct GpuState {
    window: Arc<Window>,
    device: wgpu::Device,
    queue: wgpu::Queue,
    surface: wgpu::Surface<'static>,
    surface_config: wgpu::SurfaceConfiguration,
    egui_ctx: egui::Context,
    egui_state: egui_winit::State,
    egui_renderer: egui_wgpu::Renderer,
    renderer: Renderer,
}

#[derive(Default)]
pub struct App {
    gpu: Option<GpuState>,
    state: EditorState,
    /// Last `state.window_title()` we pushed to the OS. We cache it so
    /// the per-frame `set_title` call is a no-op string compare in the
    /// steady state (X11 and Wayland both round-trip the title; KDE's
    /// taskbar redraws on each call). Cheap enough to recompute every
    /// frame; not free enough to push unconditionally.
    last_title: String,
}

impl ApplicationHandler for App {
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.gpu.is_some() {
            return;
        }

        // from_rgba can fail if the byte count doesn't match width*height*4.
        // The asset is generated, so a mismatch is a build-time bug — log and
        // fall back to no icon rather than panicking on what is otherwise
        // cosmetic state.
        let icon = Icon::from_rgba(ICON_RGBA.to_vec(), ICON_SIZE, ICON_SIZE)
            .map_err(|e| log::warn!("failed to load window icon: {e}"))
            .ok();

        let window_attrs = Window::default_attributes()
            .with_title("Locus")
            .with_inner_size(winit::dpi::LogicalSize::new(1280, 800))
            .with_window_icon(icon);
        let window = Arc::new(
            event_loop
                .create_window(window_attrs)
                .expect("create window"),
        );

        let mut instance_desc = wgpu::InstanceDescriptor::new_without_display_handle();
        instance_desc.backends = wgpu::Backends::PRIMARY;
        let instance = wgpu::Instance::new(instance_desc);

        let surface = instance
            .create_surface(window.clone())
            .expect("create surface");

        let (adapter, device, queue) = pollster::block_on(async {
            let adapter = instance
                .request_adapter(&wgpu::RequestAdapterOptions {
                    compatible_surface: Some(&surface),
                    power_preference: wgpu::PowerPreference::HighPerformance,
                    ..Default::default()
                })
                .await
                .expect("no suitable GPU adapter");

            let (device, queue) = adapter
                .request_device(&wgpu::DeviceDescriptor {
                    label: Some("vector editor device"),
                    ..Default::default()
                })
                .await
                .expect("request device");

            (adapter, device, queue)
        });

        let size = window.inner_size();
        let surface_caps = surface.get_capabilities(&adapter);
        let surface_format = surface_caps
            .formats
            .iter()
            .find(|f| f.is_srgb())
            .copied()
            .unwrap_or(surface_caps.formats[0]);

        let surface_config = wgpu::SurfaceConfiguration {
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            format: surface_format,
            width: size.width.max(1),
            height: size.height.max(1),
            present_mode: wgpu::PresentMode::AutoVsync,
            alpha_mode: surface_caps.alpha_modes[0],
            view_formats: vec![],
            desired_maximum_frame_latency: 2,
        };
        surface.configure(&device, &surface_config);

        // egui setup
        let egui_ctx = egui::Context::default();
        {
            let mut fonts = egui::FontDefinitions::default();
            egui_phosphor::add_to_fonts(&mut fonts, egui_phosphor::Variant::Regular);
            egui_ctx.set_fonts(fonts);
        }
        // Disable text selection on labels — we're a graphics editor, not a text
        // document. Selectable labels cause confusing drag-to-select behavior
        // when hovering over the structure/properties panels.
        egui_ctx.global_style_mut(|s| {
            s.interaction.selectable_labels = false;
        });
        let egui_state = egui_winit::State::new(
            egui_ctx.clone(),
            egui::ViewportId::ROOT,
            &window,
            None,
            None,
            None,
        );
        let egui_renderer = egui_wgpu::Renderer::new(
            &device,
            surface_format,
            egui_wgpu::RendererOptions::default(),
        );

        let renderer = Renderer::new(&device, surface_format);

        self.gpu = Some(GpuState {
            window,
            device,
            queue,
            surface,
            surface_config,
            egui_ctx,
            egui_state,
            egui_renderer,
            renderer,
        });
    }

    fn window_event(&mut self, event_loop: &ActiveEventLoop, _id: WindowId, event: WindowEvent) {
        let Some(gpu) = &mut self.gpu else { return };

        // Always handle RedrawRequested and CloseRequested regardless of egui
        match &event {
            WindowEvent::RedrawRequested => {
                // Let the gpu borrow end before calling self.draw()
                let _ = gpu;
                self.draw();
                return;
            }
            WindowEvent::CloseRequested => {
                event_loop.exit();
                return;
            }
            _ => {}
        }

        // Let egui handle the event first
        let response = gpu.egui_state.on_window_event(&gpu.window, &event);

        // Request a redraw so egui can update visually (hover, focus, clicks)
        if response.repaint {
            gpu.window.request_redraw();
        }

        // Only let egui consume mouse/keyboard input events, never cursor movement
        // — we always need cursor_pos updated for canvas interactions (raycasting, hover, etc.).
        let consumed = response.consumed
            && !matches!(
                event,
                WindowEvent::CursorMoved { .. } | WindowEvent::CursorLeft { .. }
            );

        if consumed {
            return;
        }

        match event {
            // Resize is never consumed by egui, but always relevant
            WindowEvent::Resized(size) if size.width > 0 && size.height > 0 => {
                gpu.surface_config.width = size.width;
                gpu.surface_config.height = size.height;
                gpu.surface.configure(&gpu.device, &gpu.surface_config);
                gpu.renderer.resize(size.width as f32, size.height as f32);
                gpu.window.request_redraw();
            }
            WindowEvent::DroppedFile(path) => {
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .map(|s| s.to_ascii_lowercase());
                let kind = match ext.as_deref() {
                    Some("svg") => Some(DroppedKind::Svg),
                    Some("png") | Some("jpg") | Some("jpeg") | Some("gif") | Some("bmp")
                    | Some("webp") | Some("tiff") | Some("tif") => Some(DroppedKind::Raster),
                    _ => None,
                };
                if let Some(kind) = kind {
                    match std::fs::read(&path) {
                        Ok(data) => match kind {
                            DroppedKind::Svg => {
                                if let Some(gpu) = &mut self.gpu {
                                    // If the document is empty there's
                                    // nothing to merge into — just open
                                    // the file. Otherwise stash the bytes
                                    // and let the choice dialog decide.
                                    if !self.state.scene_has_user_content() {
                                        match self.state.load_svg_replace(
                                            &data,
                                            &path,
                                            &mut gpu.renderer,
                                        ) {
                                            Ok(()) => {
                                                gpu.window.request_redraw();
                                                log::info!(
                                                    "Loaded {}: {}",
                                                    kind.label(),
                                                    path.display()
                                                );
                                            }
                                            Err(e) => {
                                                log::error!("Failed to load {}: {e}", kind.label())
                                            }
                                        }
                                    } else {
                                        // Replace any pending drop —
                                        // the most recent file wins.
                                        // (Rare race: user drags two
                                        // SVGs in quick succession;
                                        // we'd rather not stack
                                        // dialogs.)
                                        self.state.svg_drop_dialog =
                                            Some(crate::svg_drop_dialog::SvgDropDialogState {
                                                bytes: data,
                                                path: path.clone(),
                                            });
                                        gpu.window.request_redraw();
                                        log::info!("Drop pending choice: {}", path.display());
                                    }
                                }
                            }
                            DroppedKind::Raster => {
                                // Insert (don't trace) — this is the "use as
                                // tracing reference" path. File menu still
                                // has an explicit "Trace raster image…"
                                // entry for the one-shot conversion flow.
                                let label = path
                                    .file_stem()
                                    .and_then(|s| s.to_str())
                                    .unwrap_or("Image")
                                    .to_string();
                                if let Some(gpu) = &mut self.gpu {
                                    match self.state.insert_raster_from_bytes(
                                        &data,
                                        label,
                                        &mut gpu.renderer,
                                    ) {
                                        Ok(_id) => {
                                            gpu.window.request_redraw();
                                            log::info!(
                                                "Inserted {}: {}",
                                                kind.label(),
                                                path.display()
                                            );
                                        }
                                        Err(e) => {
                                            log::error!("Failed to insert {}: {e}", kind.label())
                                        }
                                    }
                                }
                            }
                        },
                        Err(e) => log::error!("Failed to read file: {e}"),
                    }
                }
            }
            // --- Canvas input events: guard with wants_pointer/wants_keyboard ---
            WindowEvent::MouseInput { button, state, .. } => {
                // Always track button-up so is_left_down doesn't get stuck when the
                // release happens over an egui panel (pointer moved from canvas to sidebar).
                if button == MouseButton::Left && state == ElementState::Released {
                    self.state.is_left_down = false;
                }
                if button == MouseButton::Middle && state == ElementState::Released {
                    self.state.is_panning = false;
                }
                if !gpu.egui_ctx.egui_wants_pointer_input() {
                    match button {
                        MouseButton::Middle => {
                            self.state.is_panning = state == ElementState::Pressed;
                        }
                        MouseButton::Left => {
                            if state == ElementState::Pressed {
                                self.state.is_left_down = true;
                                // Close any open canvas context menu.
                                self.state.canvas_context_menu = None;
                                // Double-click detection.
                                let now = Instant::now();
                                let is_double_click = if let Some((prev_time, prev_pos)) =
                                    self.state.last_left_press
                                {
                                    let dt = now.duration_since(prev_time);
                                    let dx = self
                                        .state
                                        .cursor_pos
                                        .map_or(f32::INFINITY, |c| (c[0] - prev_pos[0]).abs());
                                    let dy = self
                                        .state
                                        .cursor_pos
                                        .map_or(f32::INFINITY, |c| (c[1] - prev_pos[1]).abs());
                                    dt.as_millis() < 400 && dx < 5.0 && dy < 5.0
                                } else {
                                    false
                                };
                                self.state.last_left_press =
                                    self.state.cursor_pos.map(|c| (now, c));

                                if let Some(cursor) = self.state.cursor_pos {
                                    let exclude = self.state.snap_exclude();
                                    let canvas_f64 = self
                                        .state
                                        .screen_to_canvas_snapped(cursor[0], cursor[1], &exclude);
                                    match self.state.active_tool {
                                        ToolType::Select => {
                                            let mut handled = false;

                                            if is_double_click {
                                                use locus_tools::SelectionMode;
                                                match self.state.select_state.mode {
                                                    SelectionMode::Object => {
                                                        // Double-click in object mode resolves
                                                        // the leaf hit relative to the current
                                                        // group-isolation scope and then dispatches
                                                        // by what was hit:
                                                        //   - Regular group → enter it (isolation).
                                                        //   - Text node → switch to text tool and
                                                        //     start editing.
                                                        //   - anything else → enter vertex/node
                                                        //     editing mode.
                                                        let leaf_hit = SelectState::object_hit_test(
                                                            &self.state.scene,
                                                            canvas_f64,
                                                        );
                                                        let resolved_hit = leaf_hit.map(|leaf| {
                                                            self.state
                                                                .select_state
                                                                .resolve_pick_in_scope(
                                                                    &self.state.scene,
                                                                    leaf,
                                                                )
                                                        });
                                                        if let Some(node_id) = resolved_hit {
                                                            let kind = self
                                                                .state
                                                                .scene
                                                                .get(node_id)
                                                                .map(|n| n.data.clone());
                                                            let is_regular_group = matches!(
                                                                kind.as_ref(),
                                                                Some(NodeData::Group {
                                                                    kind:
                                                                        locus_scene::GroupKind::Regular,
                                                                    ..
                                                                })
                                                            );
                                                            let is_text = matches!(
                                                                kind.as_ref(),
                                                                Some(NodeData::Text(_))
                                                            );
                                                            if is_regular_group {
                                                                // Enter the group: subsequent
                                                                // clicks pick its direct children.
                                                                self.state
                                                                    .select_state
                                                                    .enter_group(
                                                                        &self.state.scene,
                                                                        node_id,
                                                                    );
                                                                // Re-tessellation rebuilds the
                                                                // per-instance alpha multipliers,
                                                                // so out-of-scope nodes dim.
                                                                gpu.renderer.mark_dirty();
                                                                handled = true;
                                                            } else if is_text {
                                                                self.state.active_tool =
                                                                    ToolType::Text;
                                                                let action =
                                                                    self.state.text_tool.on_press(
                                                                        &mut self.state.scene,
                                                                        canvas_f64,
                                                                        self.state.camera.zoom
                                                                            as f64,
                                                                    );
                                                                self.state.handle_text_action(
                                                                    action,
                                                                    &mut gpu.renderer,
                                                                );
                                                                handled = true;
                                                            } else if !self
                                                                .state
                                                                .select_state
                                                                .selected_nodes
                                                                .is_empty()
                                                                && self
                                                                    .state
                                                                    .select_state
                                                                    .is_node_selected(node_id)
                                                            {
                                                                self.state
                                                                    .select_state
                                                                    .enter_node_mode();
                                                                handled = true;
                                                            }
                                                        } else if self
                                                            .state
                                                            .select_state
                                                            .group_scope()
                                                            .is_some()
                                                        {
                                                            // Double-click on empty canvas while
                                                            // inside a group: pop one level of
                                                            // isolation. Mirrors the Escape
                                                            // shortcut and gives the user a
                                                            // discoverable mouse-only way out.
                                                            self.state
                                                                .select_state
                                                                .exit_group_scope();
                                                            gpu.renderer.mark_dirty();
                                                            handled = true;
                                                        }
                                                    }
                                                    SelectionMode::Node => {
                                                        // Double-click in node mode:
                                                        // If on a vertex → cycle its mode.
                                                        // If on an edge → insert point.
                                                        if let Some(vr) =
                                                            SelectState::hit_test_in_nodes(
                                                                &self.state.scene,
                                                                canvas_f64,
                                                                self.state.camera.zoom as f64,
                                                                &self
                                                                    .state
                                                                    .select_state
                                                                    .selected_nodes,
                                                            )
                                                        {
                                                            // Cycle vertex mode.
                                                            let old_path =
                                                                self.state.snapshot_path(vr.node);
                                                            if let Some(_new_mode) =
                                                                SelectState::cycle_vertex_mode(
                                                                    &mut self.state.scene,
                                                                    &vr,
                                                                )
                                                            {
                                                                if let Some(path) = old_path {
                                                                    self.state.history.record_undo(
                                                                        Command::SetPathData {
                                                                            id: vr.node,
                                                                            path,
                                                                        },
                                                                    );
                                                                }
                                                                gpu.renderer.mark_dirty();
                                                                handled = true;
                                                            }
                                                        } else if let Some(hit) =
                                                            SelectState::edge_hit_test(
                                                                &self.state.scene,
                                                                canvas_f64,
                                                                self.state.camera.zoom as f64,
                                                                &self
                                                                    .state
                                                                    .select_state
                                                                    .selected_nodes,
                                                            )
                                                        {
                                                            let old_path =
                                                                self.state.snapshot_path(hit.node);
                                                            if let Some(vr) =
                                                                SelectState::insert_point_on_edge(
                                                                    &mut self.state.scene,
                                                                    &hit,
                                                                )
                                                            {
                                                                if let Some(path) = old_path {
                                                                    self.state.history.record_undo(
                                                                        Command::SetPathData {
                                                                            id: hit.node,
                                                                            path,
                                                                        },
                                                                    );
                                                                }
                                                                self.state
                                                                    .select_state
                                                                    .selected
                                                                    .clear();
                                                                self.state
                                                                    .select_state
                                                                    .selected
                                                                    .push(vr);
                                                                gpu.renderer.mark_dirty();
                                                                handled = true;
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            if !handled {
                                                let (shift, alt, ctrl) = gpu.egui_ctx.input(|i| {
                                                    (
                                                        i.modifiers.shift,
                                                        i.modifiers.alt,
                                                        i.modifiers.ctrl || i.modifiers.mac_cmd,
                                                    )
                                                });
                                                self.state.select_state.on_press(
                                                    &self.state.scene,
                                                    canvas_f64,
                                                    shift,
                                                    alt,
                                                    ctrl,
                                                    self.state.camera.zoom as f64,
                                                );
                                                // If on_press started a drag,
                                                // snapshot for undo.
                                                if self.state.select_state.is_dragging_vertices() {
                                                    self.state.snapshot_selected_vertex_paths();
                                                } else if self
                                                    .state
                                                    .select_state
                                                    .is_dragging_gradient_handle()
                                                {
                                                    self.state.snapshot_gradient_for_drag();
                                                } else if self
                                                    .state
                                                    .select_state
                                                    .is_dragging_objects()
                                                    || self.state.select_state.is_rotating()
                                                    || self.state.select_state.is_scaling()
                                                {
                                                    self.state.snapshot_selected_transforms();
                                                }
                                            }
                                        }
                                        ToolType::Pen => {
                                            let action = self.state.pen_state.on_press(
                                                &mut self.state.scene,
                                                canvas_f64,
                                                self.state.camera.zoom as f64,
                                            );
                                            self.state.handle_pen_action(action, &mut gpu.renderer);
                                        }
                                        ToolType::Rectangle | ToolType::Ellipse => {
                                            self.state.shape_draw.on_press(
                                                &mut self.state.scene,
                                                canvas_f64,
                                                self.state.active_tool,
                                            );
                                            gpu.renderer.mark_dirty();
                                        }
                                        ToolType::Text => {
                                            let action = self.state.text_tool.on_press(
                                                &mut self.state.scene,
                                                canvas_f64,
                                                self.state.camera.zoom as f64,
                                            );
                                            self.state
                                                .handle_text_action(action, &mut gpu.renderer);
                                        }
                                    }
                                    gpu.window.request_redraw();
                                }
                            } else {
                                self.state.is_left_down = false;
                                match self.state.active_tool {
                                    ToolType::Select => {
                                        // If we were dragging, record the undo
                                        // command before ending the drag.
                                        if self.state.select_state.is_dragging_vertices() {
                                            self.state.record_vertex_drag_undo();
                                        } else if self
                                            .state
                                            .select_state
                                            .is_dragging_gradient_handle()
                                        {
                                            self.state.record_gradient_drag_undo();
                                        } else if self.state.select_state.is_dragging_objects()
                                            || self.state.select_state.is_rotating()
                                            || self.state.select_state.is_scaling()
                                        {
                                            self.state.record_object_drag_undo();
                                        }
                                        self.state.select_state.on_release();
                                    }
                                    ToolType::Pen => {
                                        if let Some(cursor) = self.state.cursor_pos {
                                            let exclude = self.state.snap_exclude();
                                            let canvas_f64 = self.state.screen_to_canvas_snapped(
                                                cursor[0], cursor[1], &exclude,
                                            );
                                            self.state.pen_state.on_release(
                                                &mut self.state.scene,
                                                canvas_f64,
                                                self.state.camera.zoom as f64,
                                            );
                                            gpu.renderer.mark_dirty();
                                            gpu.window.request_redraw();
                                        }
                                    }
                                    ToolType::Rectangle | ToolType::Ellipse => {
                                        if let Some(node_id) =
                                            self.state.shape_draw.on_release(&mut self.state.scene)
                                        {
                                            // Record undo: the shape was just created,
                                            // so undoing means deleting it.
                                            self.state
                                                .history
                                                .record_undo(Command::Delete { id: node_id });
                                            // Auto-select the new shape and switch to Select
                                            self.state.select_state.selected_nodes.clear();
                                            self.state.select_state.selected_nodes.push(node_id);
                                            self.state.active_tool = ToolType::Select;
                                        }
                                        gpu.renderer.mark_dirty();
                                        gpu.window.request_redraw();
                                    }
                                    _ => {}
                                }
                            }
                        }
                        MouseButton::Right if state == ElementState::Pressed => {
                            if self.state.active_tool == ToolType::Pen {
                                // Pen tool: undo last pen point.
                                let action = self.state.pen_state.undo_last(&mut self.state.scene);
                                self.state.handle_pen_action(action, &mut gpu.renderer);
                                gpu.window.request_redraw();
                            } else if self.state.active_tool == ToolType::Select
                                && let Some(cursor) = self.state.cursor_pos
                            {
                                // Select tool: open context menu on vertex or segment.
                                let canvas =
                                    self.state.camera.screen_to_canvas(cursor[0], cursor[1]);
                                let canvas_f64 = [canvas[0] as f64, canvas[1] as f64];
                                let zoom = self.state.camera.zoom as f64;
                                let screen_pos = egui::Pos2::new(cursor[0], cursor[1]);
                                let nodes = &self.state.select_state.selected_nodes;

                                if self.state.select_state.mode == locus_tools::SelectionMode::Node
                                    && !nodes.is_empty()
                                {
                                    // Node mode: check vertex first, then edge.
                                    if let Some(vr) = SelectState::hit_test_in_nodes(
                                        &self.state.scene,
                                        canvas_f64,
                                        zoom,
                                        nodes,
                                    ) {
                                        self.state.canvas_context_menu = Some(CanvasContextMenu {
                                            target: CanvasContextTarget::Vertex(vr),
                                            screen_pos,
                                            first_frame: true,
                                        });
                                    } else if let Some(hit) = SelectState::edge_hit_test(
                                        &self.state.scene,
                                        canvas_f64,
                                        zoom,
                                        nodes,
                                    ) {
                                        self.state.canvas_context_menu = Some(CanvasContextMenu {
                                            target: CanvasContextTarget::Segment(hit),
                                            screen_pos,
                                            first_frame: true,
                                        });
                                    }
                                }
                            }
                        }
                        _ => {}
                    }
                    self.state.update_cursor(&gpu.window, &gpu.egui_ctx);
                }
            }
            WindowEvent::CursorMoved { position, .. } => {
                let new_pos = [position.x as f32, position.y as f32];

                // Clear any stale snap indicator from the previous mouse
                // event; the snap-using paths below repopulate it if a
                // snap fires this frame.
                let prev_snap = self.state.last_snap.take();

                if self.state.is_panning {
                    if let Some(prev) = self.state.cursor_pos {
                        let dx = new_pos[0] - prev[0];
                        let dy = new_pos[1] - prev[1];
                        self.state.camera.pan[0] += dx;
                        self.state.camera.pan[1] += dy;
                        gpu.window.request_redraw();
                    }
                } else if self.state.is_left_down && !gpu.egui_ctx.egui_wants_pointer_input() {
                    let exclude = self.state.snap_exclude();
                    // Snap during drags only fires when the operation
                    // actually consumes a snapped *position*. For Select
                    // that excludes marquee + rotate (the user's pointer
                    // doesn't define a target point — it's a bbox corner
                    // or a rotation angle), so showing a snap marker
                    // there is just noise. For Pen / Rectangle / Ellipse
                    // / Text drags every drag is positional, so always
                    // snap.
                    let snap_during_drag = match self.state.active_tool {
                        ToolType::Select => self.state.select_state.wants_position_snap(),
                        ToolType::Pen
                        | ToolType::Rectangle
                        | ToolType::Ellipse
                        | ToolType::Text => true,
                    };
                    let canvas_f64 = if snap_during_drag {
                        self.state
                            .screen_to_canvas_snapped(new_pos[0], new_pos[1], &exclude)
                    } else {
                        let c = self.state.camera.screen_to_canvas(new_pos[0], new_pos[1]);
                        [c[0] as f64, c[1] as f64]
                    };
                    let drag_shift = gpu.egui_ctx.input(|i| i.modifiers.shift);
                    let changed = match self.state.active_tool {
                        ToolType::Select => self.state.select_state.on_drag(
                            &mut self.state.scene,
                            canvas_f64,
                            drag_shift,
                        ),
                        ToolType::Pen => self
                            .state
                            .pen_state
                            .on_drag(&mut self.state.scene, canvas_f64),
                        ToolType::Rectangle | ToolType::Ellipse => self.state.shape_draw.on_drag(
                            &mut self.state.scene,
                            canvas_f64,
                            self.state.active_tool,
                        ),
                        _ => false,
                    };
                    if changed {
                        gpu.renderer.mark_dirty();
                        gpu.window.request_redraw();
                    }
                } else if !self.state.is_left_down
                    && !gpu.egui_ctx.egui_wants_pointer_input()
                    && self.state.active_tool == ToolType::Pen
                    && self.state.pen_state.is_building()
                {
                    // Pen hover preview: show tentative segment to cursor.
                    let exclude = self.state.snap_exclude();
                    let canvas_f64 = self
                        .state
                        .screen_to_canvas_snapped(new_pos[0], new_pos[1], &exclude);
                    if self
                        .state
                        .pen_state
                        .on_move(&mut self.state.scene, canvas_f64)
                    {
                        gpu.renderer.mark_dirty();
                        gpu.window.request_redraw();
                    }
                } else if !self.state.is_left_down
                    && !gpu.egui_ctx.egui_wants_pointer_input()
                    && matches!(
                        self.state.active_tool,
                        ToolType::Pen | ToolType::Rectangle | ToolType::Ellipse | ToolType::Text
                    )
                {
                    // Hover-snap preview for placement tools: a click here
                    // would commit a point at the snap target, so show the
                    // marker now rather than waiting for the click. Select
                    // is intentionally excluded — it only snaps while
                    // dragging an existing selection (handled above), so a
                    // hover indicator would be misleading. Pen is included
                    // for the idle case (first vertex of a new path); the
                    // building case is handled in the previous arm because
                    // it also has to run `pen_state.on_move`. Side-effect:
                    // populates `self.last_snap` for the redraw block below.
                    let exclude = self.state.snap_exclude();
                    let _ = self
                        .state
                        .screen_to_canvas_snapped(new_pos[0], new_pos[1], &exclude);
                }

                self.state.cursor_pos = Some(new_pos);
                self.state.update_cursor(&gpu.window, &gpu.egui_ctx);

                // If the snap indicator visibility / position changed
                // this frame but no geometry redraw was already queued,
                // request one so the marker draws or clears.
                let prev_pos = prev_snap.map(|h| h.pos);
                let now_pos = self.state.last_snap.map(|h| h.pos);
                if prev_pos != now_pos {
                    gpu.window.request_redraw();
                }
            }
            WindowEvent::CursorLeft { .. } => {
                self.state.cursor_pos = None;
                if self.state.last_snap.take().is_some() {
                    gpu.window.request_redraw();
                }
            }
            WindowEvent::MouseWheel { delta, .. } if !gpu.egui_ctx.egui_wants_pointer_input() => {
                // Split on the *kind* of scroll source winit reports —
                // unambiguous and doesn't require device detection:
                //
                // - LineDelta = traditional mouse wheel (discrete clicks).
                //   Keep the historical "wheel zooms" behavior; Shift turns
                //   it into horizontal pan, matching most graphics editors.
                // - PixelDelta = precision touchpad / Magic Mouse two-finger
                //   scroll. Pan the canvas — that's what users expect from a
                //   two-finger gesture. Ctrl/Cmd promotes it to a zoom (the
                //   browser convention everyone is now trained on).
                let modifiers = gpu.egui_ctx.input(|i| i.modifiers);
                let ctrl = modifiers.ctrl || modifiers.mac_cmd;

                match delta {
                    winit::event::MouseScrollDelta::LineDelta(x, y) => {
                        if modifiers.shift {
                            // Shift+wheel pans horizontally. Use the y axis
                            // since most mice only report vertical wheel
                            // movement; fall back to x if both are present.
                            let dx = if x != 0.0 { x } else { y } * 40.0;
                            self.state.camera.pan[0] += dx;
                            gpu.window.request_redraw();
                        } else if let Some(cursor) = self.state.cursor_pos {
                            let factor = 1.0 + y * 0.1;
                            self.state.camera.zoom_at(factor, cursor[0], cursor[1]);
                            gpu.window.request_redraw();
                        }
                    }
                    winit::event::MouseScrollDelta::PixelDelta(pos) => {
                        if ctrl {
                            // Ctrl/Cmd + two-finger scroll = zoom centred on
                            // the cursor. The /40 divisor matches the old
                            // PixelDelta-as-zoom calibration so the gesture
                            // doesn't suddenly feel 40× more sensitive.
                            if let Some(cursor) = self.state.cursor_pos {
                                let factor = 1.0 + (pos.y as f32 / 40.0) * 0.1;
                                self.state.camera.zoom_at(factor, cursor[0], cursor[1]);
                                gpu.window.request_redraw();
                            }
                        } else {
                            // Two-finger pan. Natural direction: the canvas
                            // moves with the fingers (matches the existing
                            // middle-drag pan and macOS natural-scroll feel).
                            self.state.camera.pan[0] += pos.x as f32;
                            self.state.camera.pan[1] += pos.y as f32;
                            gpu.window.request_redraw();
                        }
                    }
                }
            }
            // Trackpad pinch-to-zoom (macOS, Windows precision touchpads).
            // `delta` is a fractional change in scale per frame — typical
            // values are in the ±0.01 range for a slow pinch. Centre the
            // zoom on the cursor so the point under the fingers stays put.
            WindowEvent::PinchGesture { delta, .. } if !gpu.egui_ctx.egui_wants_pointer_input() => {
                if let Some(cursor) = self.state.cursor_pos
                    && delta.is_finite()
                {
                    let factor = 1.0 + delta as f32;
                    self.state.camera.zoom_at(factor, cursor[0], cursor[1]);
                    gpu.window.request_redraw();
                }
            }
            WindowEvent::KeyboardInput {
                event: ref key_event,
                ..
            } if !gpu.egui_ctx.egui_wants_keyboard_input()
                && key_event.state == ElementState::Pressed =>
            {
                use winit::keyboard::{Key, NamedKey};
                let modifiers = gpu.egui_ctx.input(|i| i.modifiers);
                let ctrl = modifiers.ctrl || modifiers.mac_cmd;

                // ── Text tool editing intercept ─────────────────────
                // When the text tool is actively editing, route all
                // non-Ctrl keys to it before any other handler.
                let mut text_handled = false;
                if self.state.text_tool.is_editing() {
                    let action = match &key_event.logical_key {
                        Key::Named(NamedKey::Enter) | Key::Named(NamedKey::Escape) => {
                            self.state.text_tool.commit(&mut self.state.scene)
                        }
                        Key::Named(NamedKey::Backspace) if !ctrl => {
                            self.state.text_tool.on_backspace(&mut self.state.scene)
                        }
                        Key::Named(NamedKey::Delete) if !ctrl => {
                            self.state.text_tool.on_delete(&mut self.state.scene)
                        }
                        Key::Named(NamedKey::ArrowLeft) => self.state.text_tool.move_left(),
                        Key::Named(NamedKey::ArrowRight) => {
                            self.state.text_tool.move_right(&self.state.scene)
                        }
                        Key::Named(NamedKey::Home) => self.state.text_tool.move_home(),
                        Key::Named(NamedKey::End) => {
                            self.state.text_tool.move_end(&self.state.scene)
                        }
                        Key::Named(NamedKey::Space) if !ctrl => {
                            self.state.text_tool.on_char(&mut self.state.scene, " ")
                        }
                        Key::Character(c) if !ctrl => self
                            .state
                            .text_tool
                            .on_char(&mut self.state.scene, c.as_str()),
                        _ => TextAction::None,
                    };
                    text_handled = !matches!(action, TextAction::None);
                    self.state.handle_text_action(action, &mut gpu.renderer);
                    if text_handled {
                        gpu.window.request_redraw();
                    }
                }

                if !text_handled {
                    match &key_event.logical_key {
                        // Undo: Ctrl+Z (no shift)
                        Key::Character(c)
                            if (c.as_str() == "z" || c.as_str() == "Z")
                                    && ctrl
                                    && !modifiers.shift
                                    // Don't undo while a tool is actively building.
                                    && !self.state.pen_state.is_building()
                                    && !self.state.shape_draw.is_drawing()
                                    && !self.state.text_tool.is_editing()
                                    && self.state.history.can_undo() =>
                        {
                            self.state.undo();
                            gpu.renderer.mark_dirty();
                            gpu.window.request_redraw();
                        }
                        // Save: Ctrl+S (no shift), Save As: Ctrl+Shift+S.
                        // Both run through the same code path as the menu
                        // — `run_ui` handles the dialog and write — by
                        // synthesising a flag that the next egui pass
                        // consumes. We can't dispatch the dialog from
                        // here directly because the egui closures already
                        // own disjoint borrows of `state`.
                        Key::Character(c)
                            if (c.as_str() == "s" || c.as_str() == "S")
                                && ctrl
                                && !self.state.pen_state.is_building()
                                && !self.state.shape_draw.is_drawing()
                                && !self.state.text_tool.is_editing() =>
                        {
                            if modifiers.shift {
                                self.state.pending_save_as = true;
                            } else if self.state.current_path.is_some() && self.state.is_dirty() {
                                self.state.pending_save = true;
                            } else if self.state.current_path.is_none() {
                                // Ctrl+S on a never-saved doc still does
                                // something useful: open the Save As dialog.
                                self.state.pending_save_as = true;
                            }
                            gpu.window.request_redraw();
                        }
                        // Redo: Ctrl+Shift+Z or Ctrl+Y
                        Key::Character(c)
                            if ((c.as_str() == "z" || c.as_str() == "Z") && modifiers.shift
                                || (c.as_str() == "y" || c.as_str() == "Y")
                                    && !modifiers.shift)
                                && ctrl
                                && !self.state.pen_state.is_building()
                                && !self.state.shape_draw.is_drawing()
                                && !self.state.text_tool.is_editing()
                                && self.state.history.can_redo() =>
                        {
                            self.state.redo();
                            gpu.renderer.mark_dirty();
                            gpu.window.request_redraw();
                        }
                        Key::Named(NamedKey::Enter) | Key::Named(NamedKey::Escape) => {
                            if self.state.active_tool == ToolType::Pen
                                && self.state.pen_state.is_building()
                            {
                                let action =
                                    self.state.pen_state.finish(&mut self.state.scene, false);
                                self.state.handle_pen_action(action, &mut gpu.renderer);
                                gpu.window.request_redraw();
                            } else if self.state.active_tool == ToolType::Select
                                && self.state.select_state.mode == locus_tools::SelectionMode::Node
                            {
                                self.state.select_state.exit_node_mode();
                                gpu.window.request_redraw();
                            } else if self.state.active_tool == ToolType::Select
                                && self.state.select_state.group_scope().is_some()
                            {
                                // Pop one level out of group isolation.
                                self.state.select_state.exit_group_scope();
                                gpu.renderer.mark_dirty();
                                gpu.window.request_redraw();
                            }
                        }
                        // Arrow-key nudge: move the current selection
                        // (vertices or objects) by a screen-pixel-sized step.
                        // Step is `2 / zoom` canvas units so the visible jump
                        // stays constant regardless of zoom level; Shift
                        // multiplies by 10× for coarse moves.
                        Key::Named(key @ NamedKey::ArrowLeft)
                        | Key::Named(key @ NamedKey::ArrowRight)
                        | Key::Named(key @ NamedKey::ArrowUp)
                        | Key::Named(key @ NamedKey::ArrowDown)
                            if self.state.active_tool == ToolType::Select
                                && !ctrl
                                && !self.state.pen_state.is_building()
                                && !self.state.shape_draw.is_drawing()
                                && !self.state.text_tool.is_editing() =>
                        {
                            let zoom = self.state.camera.zoom.max(1e-6) as f64;
                            let base_px = if modifiers.shift { 20.0 } else { 2.0 };
                            let step = base_px / zoom;
                            let (dx, dy) = match key {
                                NamedKey::ArrowLeft => (-step, 0.0),
                                NamedKey::ArrowRight => (step, 0.0),
                                NamedKey::ArrowUp => (0.0, -step),
                                NamedKey::ArrowDown => (0.0, step),
                                _ => (0.0, 0.0),
                            };
                            if self.state.nudge_selection(dx, dy) {
                                gpu.renderer.mark_dirty();
                                gpu.window.request_redraw();
                            }
                        }
                        Key::Named(NamedKey::Delete) | Key::Named(NamedKey::Backspace)
                            if self.state.active_tool == ToolType::Select =>
                        {
                            // Gradient-stop focus takes priority over object
                            // delete: if the user is editing a gradient and
                            // has a stop selected in the properties panel,
                            // Delete should remove that stop.
                            let consumed = self.state.try_delete_focused_gradient_stop();
                            let deleted = consumed || self.state.delete_with_undo();
                            if deleted {
                                gpu.renderer.mark_dirty();
                                gpu.window.request_redraw();
                            }
                        }
                        // ── Zoom keybindings (Inkscape convention) ──────
                        //  1 → zoom-to-fit (entire visible scene content)
                        //  3 → zoom-to-selection (combined bounds of
                        //      currently selected nodes; no-op if empty)
                        // Plain keys; suppressed while ctrl/alt is held
                        // so they don't collide with future Ctrl+1/3
                        // bindings.
                        Key::Character(c)
                            if !ctrl
                                && !modifiers.alt
                                && !self.state.pen_state.is_building()
                                && !self.state.shape_draw.is_drawing()
                                && !self.state.text_tool.is_editing()
                                && (c.as_str() == "1" || c.as_str() == "3") =>
                        {
                            let bounds = if c.as_str() == "1" {
                                locus_bool::scene_content_bounds(&self.state.scene)
                            } else {
                                let sel = &self.state.select_state.selected_nodes;
                                if sel.is_empty() {
                                    locus_geom::Bounds::EMPTY
                                } else {
                                    locus_bool::selection_visual_bounds(&self.state.scene, sel)
                                }
                            };
                            if !bounds.is_empty() {
                                self.state
                                    .camera
                                    .zoom_to_fit(bounds, self.state.canvas_rect);
                                gpu.window.request_redraw();
                            }
                        }
                        // ── Boolean group keybindings (Inkscape-style) ──
                        //  Ctrl+ +  or  Ctrl+ =   → Union
                        //  Ctrl+ -               → Difference
                        //  Ctrl+ *               → Intersect
                        //  Ctrl+ ^               → Exclude (XOR)
                        // "=" is accepted as an unshifted alias for "+" so
                        // the binding works on US layouts without Shift.
                        // Requires ≥2 selected nodes; no-op otherwise.
                        Key::Character(c)
                            if ctrl
                                && !self.state.pen_state.is_building()
                                && !self.state.shape_draw.is_drawing()
                                && !self.state.text_tool.is_editing()
                                && self.state.select_state.selected_nodes.len() >= 2
                                && matches!(c.as_str(), "+" | "=" | "-" | "*" | "^") =>
                        {
                            let op = match c.as_str() {
                                "+" | "=" => locus_scene::BoolOp::Union,
                                "-" => locus_scene::BoolOp::Difference,
                                "*" => locus_scene::BoolOp::Intersect,
                                "^" => locus_scene::BoolOp::Exclude,
                                _ => unreachable!(),
                            };
                            let nodes = self.state.select_state.selected_nodes.clone();
                            apply_structure_action(
                                StructureAction::MakeBooleanGroup { nodes, op },
                                &mut self.state,
                            );
                            gpu.renderer.mark_dirty();
                            gpu.window.request_redraw();
                        }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
    }
}

impl App {
    fn draw(&mut self) {
        let Some(gpu) = &mut self.gpu else { return };
        draw_frame(gpu, &mut self.state);

        // Refresh the OS window title to reflect (a) which file is open
        // and (b) whether it has unsaved changes — i.e. the "★ name —
        // Locus" pattern. Done after draw_frame so any save/load that
        // ran this frame is already reflected in `state.current_path` /
        // `clean_revision` and we won't show stale state for a frame.
        let want = self.state.window_title();
        if want != self.last_title {
            gpu.window.set_title(&want);
            self.last_title = want;
        }
    }
}

fn draw_frame(gpu: &mut GpuState, state: &mut EditorState) {
    profiling::scope!("draw_frame");
    state.perf.tick();

    let output = match gpu.surface.get_current_texture() {
        wgpu::CurrentSurfaceTexture::Success(t) => t,
        wgpu::CurrentSurfaceTexture::Lost | wgpu::CurrentSurfaceTexture::Outdated => {
            gpu.surface.configure(&gpu.device, &gpu.surface_config);
            return;
        }
        other => {
            log::error!("Surface error: {other:?}");
            return;
        }
    };

    let view = output.texture.create_view(&Default::default());

    // Drain any landed trace-worker results into the live preview group
    // and kick a new trace if params have changed and the debounce
    // window has elapsed. Runs *before* egui begins so the dialog UI
    // reflects the current preview / "Tracing…" state.
    trace_dialog::poll(state, &mut gpu.renderer, &gpu.egui_ctx);

    // Same shape for the LLM dialog: drain any landed chat completion
    // result into the preview group before drawing.
    llm_dialog::poll(state, &mut gpu.renderer, &gpu.egui_ctx);

    // Script-generated-shape dialog: re-evaluate the Rhai script if any
    // input (script text / width / height / N) has changed, then update
    // the preview group. Runs synchronously on this thread because Rhai
    // eval is fast enough not to need a worker.
    script_dialog::poll(state, &mut gpu.renderer);

    // Run egui — use begin_pass/end_pass so the canvas area is NOT part of
    // any egui Ui, which lets is_pointer_over_egui() return false for it.
    let full_output = {
        profiling::scope!("egui_pass");
        let raw_input = gpu.egui_state.take_egui_input(&gpu.window);
        gpu.egui_ctx.begin_pass(raw_input);
        let (
            structure_cmds_inner,
            ui_scene_dirty_inner,
            insert_image_requested_inner,
            llm_open_requested_inner,
            script_open_requested_inner,
        ) = run_ui(&gpu.egui_ctx, state, &mut gpu.renderer);

        // Canvas context menu (right-click on vertex/segment in node mode).
        show_canvas_context_menu(&gpu.egui_ctx, state, &mut gpu.renderer);

        // Live-preview trace dialog (non-modal; coexists with all other
        // tools). Returns the action the user took this frame.
        let trace_action = trace_dialog::show(state, &gpu.egui_ctx);
        match trace_action {
            DialogAction::Apply => {
                trace_dialog::apply(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::Cancel => {
                trace_dialog::cancel(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::None => {}
        }

        // Drop-choice dialog for SVG files. Pending only when a drop
        // landed on a non-empty document; otherwise opens never get
        // here because the drop handler imports directly. Three
        // terminal choices (Replace, AddAsGroup, Cancel) plus None
        // (still open) — each terminal one clears the pending state.
        let drop_choice = crate::svg_drop_dialog::show(state, &gpu.egui_ctx);
        match drop_choice {
            crate::svg_drop_dialog::DropChoice::Replace => {
                if let Some(pending) = state.svg_drop_dialog.take() {
                    match state.load_svg_replace(&pending.bytes, &pending.path, &mut gpu.renderer) {
                        Ok(()) => {
                            gpu.window.request_redraw();
                            log::info!("Loaded SVG (replace): {}", pending.path.display());
                        }
                        Err(e) => log::error!("Failed to load SVG: {e}"),
                    }
                }
            }
            crate::svg_drop_dialog::DropChoice::AddAsGroup => {
                if let Some(pending) = state.svg_drop_dialog.take() {
                    match state.load_svg_as_group(&pending.bytes, &pending.path, &mut gpu.renderer)
                    {
                        Ok(_id) => {
                            gpu.window.request_redraw();
                            log::info!("Loaded SVG (as group): {}", pending.path.display());
                        }
                        Err(e) => log::error!("Failed to load SVG as group: {e}"),
                    }
                }
            }
            crate::svg_drop_dialog::DropChoice::Cancel => {
                state.svg_drop_dialog = None;
                gpu.window.request_redraw();
            }
            crate::svg_drop_dialog::DropChoice::None => {}
        }

        // Live-preview LLM-generation dialog. Same shape as the trace
        // dialog: returns Apply / Cancel / None and we route accordingly.
        let llm_action = llm_dialog::show(state, &gpu.egui_ctx, &mut gpu.renderer);
        match llm_action {
            DialogAction::Apply => {
                llm_dialog::apply(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::Cancel => {
                llm_dialog::cancel(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::None => {}
        }

        // Live-preview script-shape dialog. Same Apply / Cancel / None
        // contract; the dialog's own `poll` above already updated the
        // preview group before this `show` call.
        let script_action = script_dialog::show(state, &gpu.egui_ctx);
        match script_action {
            DialogAction::Apply => {
                script_dialog::apply(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::Cancel => {
                script_dialog::cancel(state, &mut gpu.renderer);
                gpu.window.request_redraw();
            }
            DialogAction::None => {}
        }

        // Capture the canvas rect (area not covered by egui panels) before ending the pass.
        #[expect(deprecated)] // content_rect may not exist in this egui version yet
        let avail = gpu.egui_ctx.available_rect();
        state.canvas_rect = [avail.min.x, avail.min.y, avail.width(), avail.height()];

        // Stash outputs for the outer scope via tuple.
        (
            gpu.egui_ctx.end_pass(),
            structure_cmds_inner,
            ui_scene_dirty_inner,
            insert_image_requested_inner,
            llm_open_requested_inner,
            script_open_requested_inner,
        )
    };
    let (
        full_output,
        structure_cmds,
        ui_scene_dirty,
        insert_image_requested,
        llm_open_requested,
        script_open_requested,
    ) = full_output;

    // File → Generate SVG from prompt…: opens the LLM dialog. The
    // dialog itself loads the API key from the keychain on construction
    // (so it can show a paste-key fallback if the keychain is missing).
    if llm_open_requested && state.llm_dialog.is_none() {
        llm_dialog::open(state);
        gpu.window.request_redraw();
    }

    // File → Generate shape from script…: opens the Rhai script dialog
    // with the default star preset. Like the LLM dialog, opens lazily
    // here (post-`run_ui`) so we have the full `&mut EditorState`.
    if script_open_requested && state.script_dialog.is_none() {
        script_dialog::open(state);
        gpu.window.request_redraw();
    }

    // File → Insert Image…: opens a file dialog and inserts the chosen image
    // as a Raster scene node. Lives here (after run_ui returns) because the
    // helper needs the full `&mut EditorState`, which is borrowed through
    // disjoint field refs inside run_ui.
    if insert_image_requested
        && let Some(path) = rfd::FileDialog::new()
            .add_filter(
                "Raster images",
                &["png", "jpg", "jpeg", "gif", "bmp", "webp", "tiff", "tif"],
            )
            .pick_file()
    {
        match std::fs::read(&path) {
            Ok(data) => {
                let label = path
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("Image")
                    .to_string();
                match state.insert_raster_from_bytes(&data, label, &mut gpu.renderer) {
                    Ok(_id) => {
                        gpu.window.request_redraw();
                        log::info!("Inserted raster image: {}", path.display());
                    }
                    Err(e) => log::error!("Failed to insert raster image: {e}"),
                }
            }
            Err(e) => log::error!("Failed to read file: {e}"),
        }
    }

    // Mark dirty if the UI changed the scene (e.g. visibility toggle).
    if ui_scene_dirty {
        gpu.renderer.mark_dirty();
    }

    // Apply structure commands from the UI (after egui pass, before renderer.prepare).
    for action in structure_cmds {
        apply_structure_action(action, state);
        gpu.renderer.mark_dirty();
    }

    // Handle pending zoom-to-fit (e.g. after loading an SVG).
    if state.pending_zoom_to_fit {
        state.pending_zoom_to_fit = false;
        let bounds = locus_bool::scene_content_bounds(&state.scene);
        state.camera.zoom_to_fit(bounds, state.canvas_rect);
    }

    gpu.egui_state
        .handle_platform_output(&gpu.window, full_output.platform_output);

    let paint_jobs = gpu
        .egui_ctx
        .tessellate(full_output.shapes, full_output.pixels_per_point);

    let screen_descriptor = egui_wgpu::ScreenDescriptor {
        size_in_pixels: [gpu.surface_config.width, gpu.surface_config.height],
        pixels_per_point: gpu.window.scale_factor() as f32,
    };

    for (id, delta) in &full_output.textures_delta.set {
        gpu.egui_renderer
            .update_texture(&gpu.device, &gpu.queue, *id, delta);
    }

    let mut encoder = gpu
        .device
        .create_command_encoder(&wgpu::CommandEncoderDescriptor {
            label: Some("frame encoder"),
        });

    gpu.egui_renderer.update_buffers(
        &gpu.device,
        &gpu.queue,
        &mut encoder,
        &paint_jobs,
        &screen_descriptor,
    );

    // Update camera and prepare vector scene
    gpu.renderer.set_camera(
        gpu.surface_config.width as f32,
        gpu.surface_config.height as f32,
        state.camera.pan,
        state.camera.zoom,
    );
    // Sync grid spacing from snap settings to the renderer.
    gpu.renderer.grid_minor_spacing = state.snap.grid_size as f32;
    gpu.renderer.grid_major_spacing = state.snap.grid_size as f32 * 10.0;
    gpu.renderer.checker_fixed_size = state.checker_fixed_size;

    // Update text cursor info for rendering.
    gpu.renderer.text_cursor = if state.text_tool.is_editing() {
        state
            .text_tool
            .cursor_local_position(&state.scene)
            .and_then(|(x, top, bottom)| {
                state
                    .text_tool
                    .editing_world_transform(&state.scene)
                    .map(|world| locus_render::TextCursorInfo {
                        local_x: x as f32,
                        local_top: top as f32,
                        local_bottom: bottom as f32,
                        world_transform: [
                            world.a as f32,
                            world.c as f32,
                            world.b as f32,
                            world.d as f32,
                            world.tx as f32,
                            world.ty as f32,
                        ],
                    })
            })
    } else {
        None
    };
    gpu.renderer.text_editing_node = state.text_tool.editing_node();

    // Snap indicator: encode the most recent snap target (if any) for
    // the renderer's handle layer to draw a small marker at the snap
    // point. Kind: 0 = vertex, 1 = edge, 2 = grid.
    gpu.renderer.snap_indicator = state.last_snap.map(|hit| {
        let kind = match hit.kind {
            crate::snap::SnapKind::Vertex => 0u8,
            crate::snap::SnapKind::Edge => 1u8,
            crate::snap::SnapKind::Grid => 2u8,
        };
        (hit.pos, kind)
    });

    {
        profiling::scope!("renderer.prepare");
        gpu.renderer
            .prepare(&gpu.device, &gpu.queue, &state.scene, &state.select_state);
    }

    // Create render pass — forget_lifetime() decouples the pass from the encoder
    // borrow, which is required by egui-wgpu 0.31's render() expecting RenderPass<'static>.
    {
        let mut pass = encoder
            .begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("main pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &view,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: 0.15,
                            g: 0.15,
                            b: 0.15,
                            a: 1.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                    depth_slice: None,
                })],
                depth_stencil_attachment: None,
                ..Default::default()
            })
            .forget_lifetime();

        // Draw vector scene
        gpu.renderer.render(&mut pass);

        // Draw egui on top
        gpu.egui_renderer
            .render(&mut pass, &paint_jobs, &screen_descriptor);
    }

    {
        profiling::scope!("gpu_submit");
        gpu.queue.submit(Some(encoder.finish()));
    }
    {
        profiling::scope!("gpu_present");
        output.present();
    }

    for id in &full_output.textures_delta.free {
        gpu.egui_renderer.free_texture(id);
    }

    // Continuous redraw: schedule another frame immediately. This gives us a
    // real FPS reading in the HUD and avoids the "frozen UI" feel when egui
    // doesn't explicitly ask for a repaint. Cost is one GPU frame per vsync
    // tick (~16ms at 60Hz); scene re-tessellation is still gated by
    // `renderer.mark_dirty()`, so we're only paying for the draw itself.
    //
    // (The older egui-driven conditional redraw is subsumed by this — we
    // redraw unconditionally, which is a strict superset.)
    gpu.window.request_redraw();

    // Mark the frame boundary for profilers (Tracy, etc.). No-op when the
    // `tracy` feature isn't enabled on the editor binary.
    profiling::finish_frame!();
}
